import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BXzK3EA4.js";const A=JSON.parse('{"title":"세력과 외교, 전쟁과 공성 규칙","description":"","frontmatter":{},"headers":[],"relativePath":"rules/Rules-FactionsWarfare.md","filePath":"rules/Rules-FactionsWarfare.md"}'),l={name:"rules/Rules-FactionsWarfare.md"};function o(i,t,c,h,R,n){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="세력과-외교-전쟁과-공성-규칙" tabindex="-1">세력과 외교, 전쟁과 공성 규칙 <a class="header-anchor" href="#세력과-외교-전쟁과-공성-규칙" aria-label="Permalink to &quot;세력과 외교, 전쟁과 공성 규칙&quot;">​</a></h1><blockquote><p>출처: docs/game-logic/Factions-and-Diplomacy.md, docs/game-logic/Warfare-and-Sieges.md — 계약 수치는 구현 상수를 우선한다.</p></blockquote><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>세력 정치는 호감도 하나가 아니다. 개인 신뢰와 대중 평판과 지역별 정통성과 이행 가능한 약속과 집단 불만의 그래프로 관계를 읽는다. 전쟁은 병력 수 비교가 아니라 접근로와 보급과 사기와 퇴로와 점령 후 유지 능력을 둘러싼 연속 과정이다.</p><h2 id="핵심-수치" tabindex="-1">핵심 수치 <a class="header-anchor" href="#핵심-수치" aria-label="Permalink to &quot;핵심 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">값</th><th>범위</th></tr></thead><tbody><tr><td>신뢰 <code>T[A,B]</code></td><td style="text-align:right;">기본 0</td><td>-100~100</td></tr><tr><td>평판 <code>R[F,a]</code></td><td style="text-align:right;">기본 0</td><td>-100~100</td></tr><tr><td>정통성 <code>L[F,n,k]</code></td><td style="text-align:right;">현지 신규 주장 20</td><td>0~100</td></tr><tr><td>정치 자본 <code>PC</code></td><td style="text-align:right;">기본 0</td><td>0~100</td></tr><tr><td>불만 <code>G</code></td><td style="text-align:right;">기본 0</td><td>0~100</td></tr><tr><td>결속 <code>C</code> (외교)</td><td style="text-align:right;">기본 0</td><td>0~100</td></tr><tr><td>지렛대 <code>V</code></td><td style="text-align:right;">기본 0</td><td>0~1</td></tr><tr><td>이행 신뢰도 <code>Rel</code></td><td style="text-align:right;"><code>clamp(1 - 0.50*부족 - 0.30*고립 - 0.40*과확장, 0, 1)</code></td><td>0~1</td></tr><tr><td>신뢰변화</td><td style="text-align:right;"><code>clamp(sum(사건영향 * 신빙성), -25, 25)</code></td><td>-25~25</td></tr><tr><td>갱신 신뢰 <code>T&#39;</code></td><td style="text-align:right;"><code>clamp(T + 신뢰변화 + 기준선이동, -100, 100)</code></td><td>-100~100</td></tr><tr><td>압력</td><td style="text-align:right;"><code>clamp(0.45*불만 + 0.35*결속 + 0.20*(100*지렛대), 0, 100)</code></td><td>0~100</td></tr><tr><td>일반 회의 비용</td><td style="text-align:right;">5 정치 자본</td><td>0~100</td></tr><tr><td>긴급 심의 비용</td><td style="text-align:right;">10 정치 자본</td><td>0~100</td></tr><tr><td>연합 전체 안건</td><td style="text-align:right;">20 정치 자본</td><td>0~100</td></tr><tr><td>조직화 압력</td><td style="text-align:right;">40</td><td>0~100</td></tr><tr><td>위기 압력</td><td style="text-align:right;">70</td><td>0~100</td></tr><tr><td>강제 요구 지렛대</td><td style="text-align:right;">0.75</td><td>0~1</td></tr><tr><td>일반 협약 재검토</td><td style="text-align:right;">3주</td><td>1주~12주</td></tr><tr><td>강제 요구 유지</td><td style="text-align:right;">2주 연속</td><td>—</td></tr><tr><td>전력 <code>S</code></td><td style="text-align:right;">기본 100</td><td>0~100</td></tr><tr><td>결속 <code>C</code> (작전)</td><td style="text-align:right;">기본 70</td><td>0~100</td></tr><tr><td>보급일 <code>D</code></td><td style="text-align:right;">기본 3일</td><td>0일~6일</td></tr><tr><td>피로 <code>F</code></td><td style="text-align:right;">기본 0</td><td>0~100</td></tr><tr><td>접근 용량 <code>A</code></td><td style="text-align:right;">기본 2파티</td><td>1~3</td></tr><tr><td>방어 엄폐 <code>V</code></td><td style="text-align:right;">기본 10</td><td>0~30</td></tr><tr><td>압박 <code>P</code> · 돌파 <code>B</code></td><td style="text-align:right;">기본 0</td><td>0~100</td></tr><tr><td>피로계수</td><td style="text-align:right;"><code>clamp(1 - F/200, 0.5, 1)</code></td><td>0.5~1</td></tr><tr><td>적재계수</td><td style="text-align:right;"><code>clamp(1 - max(0, 적재율-80)/100, 0.8, 1)</code></td><td>0.8~1</td></tr><tr><td>압박증가</td><td style="text-align:right;"><code>clamp(6 + floor((공격작전력-수비작전력)/20) - 고립, 1, 12)</code></td><td>1~12</td></tr><tr><td>패주손실</td><td style="text-align:right;"><code>clamp(15 + 5*고립 + floor(F/10), 15, 35)</code></td><td>15~35</td></tr><tr><td>주둔요구</td><td style="text-align:right;"><code>clamp(20 + 10*적대접근로수 + floor(5*과확장), 20, 80)</code></td><td>20~80</td></tr><tr><td>고립 단계</td><td style="text-align:right;">정상 0 / 부분 봉쇄 1 / 완전 차단 2</td><td>0~2</td></tr><tr><td>과확장</td><td style="text-align:right;">물류 공유 척도</td><td>0~2</td></tr><tr><td>위험 추가 손실</td><td style="text-align:right;">0</td><td>0~4</td></tr><tr><td>철수 피로</td><td style="text-align:right;">+15</td><td>0~100</td></tr><tr><td>압박 일일 증가</td><td style="text-align:right;">6</td><td>1~12</td></tr><tr><td>점령 직후 치안</td><td style="text-align:right;">20</td><td>0~100</td></tr><tr><td>돌파 문턱</td><td style="text-align:right;"><code>P&gt;=40</code> 뒤 <code>B</code> 누적</td><td>—</td></tr><tr><td>무보급 전투 계수</td><td style="text-align:right;">0.60</td><td>—</td></tr><tr><td>Rel 검산</td><td style="text-align:right;">부족 0.30 · 고립 0.40 · 과확장 0.50 → 0.53</td><td>—</td></tr><tr><td>압력 검산</td><td style="text-align:right;">불만 80 · 결속 60 · 지렛대 0.8 → 73</td><td>—</td></tr><tr><td>압박증가 검산</td><td style="text-align:right;">공격 90 · 수비 78 · 고립 0 → 6</td><td>—</td></tr><tr><td>피로계수 검산</td><td style="text-align:right;">피로 40 → 0.8</td><td>—</td></tr><tr><td>패주손실 검산</td><td style="text-align:right;">고립 2 · 피로 70 → 32</td><td>—</td></tr></tbody></table><h2 id="조항" tabindex="-1">조항 <a class="header-anchor" href="#조항" aria-label="Permalink to &quot;조항&quot;">​</a></h2><h3 id="rwarfare-01-정치는-그래프다" tabindex="-1">RWARFARE-01 정치는 그래프다 <a class="header-anchor" href="#rwarfare-01-정치는-그래프다" aria-label="Permalink to &quot;RWARFARE-01 정치는 그래프다&quot;">​</a></h3><p>호감도 하나로 외교를 접지 않는다. 개인 신뢰와 청중별 평판과 근거별 정통성과 이행 가능한 약속과 집단 불만의 그래프로 판정한다.</p><h3 id="rwarfare-02-신뢰-t" tabindex="-1">RWARFARE-02 신뢰 T <a class="header-anchor" href="#rwarfare-02-신뢰-t" aria-label="Permalink to &quot;RWARFARE-02 신뢰 T&quot;">​</a></h3><p>신뢰 <code>T[A,B]</code>의 범위는 -100~100이다. 기본값은 0이다. 개인과 기관 사이 협조는 이 값에서 읽는다.</p><h3 id="rwarfare-03-평판-r" tabindex="-1">RWARFARE-03 평판 R <a class="header-anchor" href="#rwarfare-03-평판-r" aria-label="Permalink to &quot;RWARFARE-03 평판 R&quot;">​</a></h3><p>평판 <code>R[F,a]</code>의 범위는 -100~100이다. 기본값은 0이다. 청중별 공개 평가만 이 축에 남긴다.</p><h3 id="rwarfare-04-정통성-l" tabindex="-1">RWARFARE-04 정통성 L <a class="header-anchor" href="#rwarfare-04-정통성-l" aria-label="Permalink to &quot;RWARFARE-04 정통성 L&quot;">​</a></h3><p>정통성 <code>L[F,n,k]</code>의 범위는 0~100이다. 현지 신규 주장은 20으로 연다. 식량·전력·안전 같은 근거별 승인이 이 값에 묶인다.</p><h3 id="rwarfare-05-정치-자본-pc" tabindex="-1">RWARFARE-05 정치 자본 PC <a class="header-anchor" href="#rwarfare-05-정치-자본-pc" aria-label="Permalink to &quot;RWARFARE-05 정치 자본 PC&quot;">​</a></h3><p>정치 자본 <code>PC</code>의 범위는 0~100이다. 기본값은 0이다. 회의와 보증과 연합 행동의 비용으로만 쓴다.</p><h3 id="rwarfare-06-불만-결속-지렛대" tabindex="-1">RWARFARE-06 불만 결속 지렛대 <a class="header-anchor" href="#rwarfare-06-불만-결속-지렛대" aria-label="Permalink to &quot;RWARFARE-06 불만 결속 지렛대&quot;">​</a></h3><p>불만 <code>G</code>와 결속 <code>C</code>의 범위는 0~100이고 기본값은 0이다. 지렛대 <code>V</code>의 범위는 0~1이고 기본값은 0이다. 결속은 집단 행동을 조직하는 능력이고 지렛대는 상대를 강제할 실질 수단이다.</p><h3 id="rwarfare-07-이행-신뢰도-rel" tabindex="-1">RWARFARE-07 이행 신뢰도 Rel <a class="header-anchor" href="#rwarfare-07-이행-신뢰도-rel" aria-label="Permalink to &quot;RWARFARE-07 이행 신뢰도 Rel&quot;">​</a></h3><p><code>Rel = clamp(1 - 0.50*부족 - 0.30*고립 - 0.40*과확장, 0, 1)</code>이다. 범위는 0~1로 가둔다. 제안 수용과 계약 위험은 이 값에서 읽는다.</p><h3 id="rwarfare-08-신뢰-갱신" tabindex="-1">RWARFARE-08 신뢰 갱신 <a class="header-anchor" href="#rwarfare-08-신뢰-갱신" aria-label="Permalink to &quot;RWARFARE-08 신뢰 갱신&quot;">​</a></h3><p><code>신뢰변화 = clamp(sum(사건영향 * 신빙성), -25, 25)</code>이다. <code>T&#39; = clamp(T + 신뢰변화 + 기준선이동, -100, 100)</code>으로 덮는다. 한 번의 사건으로 -25 아래나 25 위를 직접 밀어내지 못한다.</p><h3 id="rwarfare-09-압력-산식" tabindex="-1">RWARFARE-09 압력 산식 <a class="header-anchor" href="#rwarfare-09-압력-산식" aria-label="Permalink to &quot;RWARFARE-09 압력 산식&quot;">​</a></h3><p><code>압력 = clamp(0.45*불만 + 0.35*결속 + 0.20*(100*지렛대), 0, 100)</code>이다. 불만과 결속은 0~100이고 지렛대는 0~1이라 100을 곱해 같은 척도로 맞춘다. 압력의 범위는 0~100이다.</p><h3 id="rwarfare-10-불가능한-약속" tabindex="-1">RWARFARE-10 불가능한 약속 <a class="header-anchor" href="#rwarfare-10-불가능한-약속" aria-label="Permalink to &quot;RWARFARE-10 불가능한 약속&quot;">​</a></h3><p>모든 제안은 먼저 실제 경로와 물자와 권한과 배타 계약 충돌을 검사한다. 불가능한 약속은 높은 교섭 능력으로 통과시키지 못한다.</p><h3 id="rwarfare-11-회의-비용" tabindex="-1">RWARFARE-11 회의 비용 <a class="header-anchor" href="#rwarfare-11-회의-비용" aria-label="Permalink to &quot;RWARFARE-11 회의 비용&quot;">​</a></h3><p>일반 회의는 5 정치 자본이다. 긴급 심의는 10 정치 자본이고 연합 전체 안건은 20 정치 자본이다. 세 비용 모두 0~100 안에 가둔다.</p><h3 id="rwarfare-12-정치-자본의-한계" tabindex="-1">RWARFARE-12 정치 자본의 한계 <a class="header-anchor" href="#rwarfare-12-정치-자본의-한계" aria-label="Permalink to &quot;RWARFARE-12 정치 자본의 한계&quot;">​</a></h3><p>정치 자본 지출은 신뢰나 정통성을 직접 바꾸지 못한다. 그 값은 지출이 뒷받침한 행동의 기록된 결과로만 바뀐다.</p><h3 id="rwarfare-13-강제-요구-문턱" tabindex="-1">RWARFARE-13 강제 요구 문턱 <a class="header-anchor" href="#rwarfare-13-강제-요구-문턱" aria-label="Permalink to &quot;RWARFARE-13 강제 요구 문턱&quot;">​</a></h3><p>조직화 압력은 40이고 위기 압력은 70이다. 강제 요구 지렛대는 0.75다. 압력 70 이상과 지렛대 0.75 이상이 2주 연속일 때만 파업·봉쇄·분리를 연다.</p><h3 id="rwarfare-14-협약-재검토" tabindex="-1">RWARFARE-14 협약 재검토 <a class="header-anchor" href="#rwarfare-14-협약-재검토" aria-label="Permalink to &quot;RWARFARE-14 협약 재검토&quot;">​</a></h3><p>일반 협약 재검토의 기본은 3주다. 범위는 1주~12주다.</p><h3 id="rwarfare-15-고립과-정통성" tabindex="-1">RWARFARE-15 고립과 정통성 <a class="header-anchor" href="#rwarfare-15-고립과-정통성" aria-label="Permalink to &quot;RWARFARE-15 고립과 정통성&quot;">​</a></h3><p>고립은 외부 약속만 약화시킨다. 현지 통치의 정통성을 자동으로 깎지 않는다.</p><h3 id="rwarfare-16-후계와-동시-제안" tabindex="-1">RWARFARE-16 후계와 동시 제안 <a class="header-anchor" href="#rwarfare-16-후계와-동시-제안" aria-label="Permalink to &quot;RWARFARE-16 후계와 동시 제안&quot;">​</a></h3><p>후계자가 바뀌면 개인 약속과 제도 약속을 구분해 재검토한다. 새 후계의 성명은 후계·이름 로스터·세계 원장을 따른다. 동시 제안은 같은 주간 스냅샷으로 평가한 뒤 명령 ID 순서로 정산한다.</p><h3 id="rwarfare-17-rel-검산" tabindex="-1">RWARFARE-17 Rel 검산 <a class="header-anchor" href="#rwarfare-17-rel-검산" aria-label="Permalink to &quot;RWARFARE-17 Rel 검산&quot;">​</a></h3><p>부족 0.30 고립 0.40 과확장 0.50이면 감점은 0.15와 0.12와 0.20이다. <code>Rel=clamp(1-0.15-0.12-0.20,0,1)=0.53</code>이다. 신뢰 60이어도 실제 배송 성공률이 53%면 장기 전력 공급 협약은 거부되거나 담보·단계 이행이 붙는다.</p><h3 id="rwarfare-18-압력-검산" tabindex="-1">RWARFARE-18 압력 검산 <a class="header-anchor" href="#rwarfare-18-압력-검산" aria-label="Permalink to &quot;RWARFARE-18 압력 검산&quot;">​</a></h3><p>불만 80 결속 60 지렛대 0.8이면 <code>압력=clamp(0.45*80+0.35*60+0.20*(100*0.8),0,100)=73</code>이다. 지렛대 0.75 이상과 함께 2주 연속이면 강제 요구가 열린다. 실패 원인이 제3자 봉쇄이고 사전 통보했다면 신빙성 계수로 신뢰 손실을 줄인다.</p><h3 id="rwarfare-19-전쟁의-축" tabindex="-1">RWARFARE-19 전쟁의 축 <a class="header-anchor" href="#rwarfare-19-전쟁의-축" aria-label="Permalink to &quot;RWARFARE-19 전쟁의 축&quot;">​</a></h3><p>전쟁은 병력 수 비교가 아니다. 접근로와 보급과 사기와 퇴로와 점령 후 유지 능력의 연속 과정으로 푼다. 공성 접근로와 보급과 퇴로는 4방향 시야와 공간으로 계획한다.</p><h3 id="rwarfare-20-전력과-결속" tabindex="-1">RWARFARE-20 전력과 결속 <a class="header-anchor" href="#rwarfare-20-전력과-결속" aria-label="Permalink to &quot;RWARFARE-20 전력과 결속&quot;">​</a></h3><p>전력 <code>S</code>의 범위는 0~100이고 기본값은 100이다. 작전 결속 <code>C</code>의 범위는 0~100이고 기본값은 70이다. 전력은 전투 가능 인원·장비이고 결속은 대형 유지와 철수 통제다.</p><h3 id="rwarfare-21-보급일과-피로" tabindex="-1">RWARFARE-21 보급일과 피로 <a class="header-anchor" href="#rwarfare-21-보급일과-피로" aria-label="Permalink to &quot;RWARFARE-21 보급일과 피로&quot;">​</a></h3><p>보급일 <code>D</code>의 범위는 0~6이고 기본값은 3일이다. 피로 <code>F</code>의 범위는 0~100이고 기본값은 0이다. 보급일은 작전 지속 기간이고 피로는 전투 효율과 패주 손실에 붙는다.</p><h3 id="rwarfare-22-접근-용량과-엄폐" tabindex="-1">RWARFARE-22 접근 용량과 엄폐 <a class="header-anchor" href="#rwarfare-22-접근-용량과-엄폐" aria-label="Permalink to &quot;RWARFARE-22 접근 용량과 엄폐&quot;">​</a></h3><p>접근 용량 <code>A</code>의 범위는 1~3이고 기본값은 2파티다. 방어 엄폐 <code>V</code>의 범위는 0~30이고 기본값은 10이다. 압박 <code>P</code>와 돌파 <code>B</code>의 범위는 0~100이고 기본값은 0이다.</p><h3 id="rwarfare-23-전투-계수" tabindex="-1">RWARFARE-23 전투 계수 <a class="header-anchor" href="#rwarfare-23-전투-계수" aria-label="Permalink to &quot;RWARFARE-23 전투 계수&quot;">​</a></h3><p><code>피로계수 = clamp(1 - F/200, 0.5, 1)</code>이다. <code>적재계수 = clamp(1 - max(0, 적재율-80)/100, 0.8, 1)</code>이다. 전투는 시작 시 확정된 전투 컨텍스트만 쓰고 종료 결과는 <code>ResultId</code>로 한 번만 캠페인에 반영한다.</p><h3 id="rwarfare-24-압박-증가" tabindex="-1">RWARFARE-24 압박 증가 <a class="header-anchor" href="#rwarfare-24-압박-증가" aria-label="Permalink to &quot;RWARFARE-24 압박 증가&quot;">​</a></h3><p><code>압박증가 = clamp(6 + floor((공격작전력-수비작전력)/20) - 고립, 1, 12)</code>이다. 압박 일일 증가 기본값은 6이고 범위는 1~12다. 고립은 정상 0 부분 봉쇄 1 완전 차단 2이며 물류 문서를 그대로 쓴다.</p><h3 id="rwarfare-25-패주와-주둔" tabindex="-1">RWARFARE-25 패주와 주둔 <a class="header-anchor" href="#rwarfare-25-패주와-주둔" aria-label="Permalink to &quot;RWARFARE-25 패주와 주둔&quot;">​</a></h3><p><code>패주손실 = clamp(15 + 5*고립 + floor(F/10), 15, 35)</code>이다. <code>주둔요구 = clamp(20 + 10*적대접근로수 + floor(5*과확장), 20, 80)</code>이다. 과확장은 물류의 공유 0~2 척도를 그대로 가져온다.</p><h3 id="rwarfare-26-부가-손실" tabindex="-1">RWARFARE-26 부가 손실 <a class="header-anchor" href="#rwarfare-26-부가-손실" aria-label="Permalink to &quot;RWARFARE-26 부가 손실&quot;">​</a></h3><p>위험 추가 손실의 기본값은 0이고 범위는 0~4다. 철수 피로는 +15이며 범위는 0~100이다. 점령 직후 치안은 20이고 범위는 0~100이다.</p><h3 id="rwarfare-27-무보급" tabindex="-1">RWARFARE-27 무보급 <a class="header-anchor" href="#rwarfare-27-무보급" aria-label="Permalink to &quot;RWARFARE-27 무보급&quot;">​</a></h3><p>탄약과 식량을 묶은 보급일이 0이면 전투 계수는 0.60이다. 다음 무보급 공성일을 지속하지 못한다.</p><h3 id="rwarfare-28-고립의-대가" tabindex="-1">RWARFARE-28 고립의 대가 <a class="header-anchor" href="#rwarfare-28-고립의-대가" aria-label="Permalink to &quot;RWARFARE-28 고립의 대가&quot;">​</a></h3><p>고립은 압박 증가를 낮춘다. 철수·패주 손실은 커지고 점령지 수리는 막힌다.</p><h3 id="rwarfare-29-퇴로-검사" tabindex="-1">RWARFARE-29 퇴로 검사 <a class="header-anchor" href="#rwarfare-29-퇴로-검사" aria-label="Permalink to &quot;RWARFARE-29 퇴로 검사&quot;">​</a></h3><p>퇴로가 봉쇄되면 질서 철수 대신 긴급 탈출이나 항복이나 패주만 남는다. 퇴로 그래프 검사 <code>LegalFallback</code>을 통과하지 못하면 패주손실을 적용한다.</p><h3 id="rwarfare-30-점령의-한계" tabindex="-1">RWARFARE-30 점령의 한계 <a class="header-anchor" href="#rwarfare-30-점령의-한계" aria-label="Permalink to &quot;RWARFARE-30 점령의 한계&quot;">​</a></h3><p>점령 승리는 시설 복구와 주민 협력을 자동 부여하지 않는다. 동시 공격은 접근 용량만큼만 완전 전력을 쓰고 나머지는 예비·지원으로 정산한다.</p><h3 id="rwarfare-31-상태-전이" tabindex="-1">RWARFARE-31 상태 전이 <a class="header-anchor" href="#rwarfare-31-상태-전이" aria-label="Permalink to &quot;RWARFARE-31 상태 전이&quot;">​</a></h3><p>흐름은 접근에서 시작해 공격 명령이면 교전으로 압박 작전이면 봉쇄로 간다. 봉쇄는 <code>P&gt;=40</code>과 <code>B</code> 누적에서 돌파로 넘긴다. 교전은 합법 퇴로가 있으면 질서철수 결속이 붕괴하면 패주다.</p><h3 id="rwarfare-32-점령-이후" tabindex="-1">RWARFARE-32 점령 이후 <a class="header-anchor" href="#rwarfare-32-점령-이후" aria-label="Permalink to &quot;RWARFARE-32 점령 이후&quot;">​</a></h3><p>돌파에서 목표를 확보하면 점령이다. 점령 다음은 주둔·수리·협상의 안정화다.</p><h3 id="rwarfare-33-작전-검산" tabindex="-1">RWARFARE-33 작전 검산 <a class="header-anchor" href="#rwarfare-33-작전-검산" aria-label="Permalink to &quot;RWARFARE-33 작전 검산&quot;">​</a></h3><p>공격 작전력 90 수비 작전력 78 고립 0이면 <code>압박증가=clamp(6+floor(12/20),1,12)=6</code>이다. 공격대 피로 40이면 피로계수는 <code>clamp(1-0.2,0.5,1)=0.8</code>이다. 같은 공격대가 고립 2 피로 70으로 패주하면 <code>패주손실=clamp(15+10+7,15,35)=32</code>다.</p><h2 id="판정-순서" tabindex="-1">판정 순서 <a class="header-anchor" href="#판정-순서" aria-label="Permalink to &quot;판정 순서&quot;">​</a></h2><ol><li>실제 경로와 물자와 권한과 배타 계약 충돌을 먼저 검사한다. 불가능한 약속은 여기서 끊는다.</li><li><code>Rel</code>을 <code>clamp(1 - 0.50*부족 - 0.30*고립 - 0.40*과확장, 0, 1)</code>로 구한다.</li><li>신뢰변화와 <code>T&#39;</code>를 자른 뒤 평판과 정통성을 같은 주간 스냅샷으로 읽는다.</li><li>정치 자본 비용을 뺀다. 일반 회의 5 긴급 심의 10 연합 전체 안건 20이다.</li><li>압력을 계산한다. 70 이상과 지렛대 0.75 이상이 2주 연속일 때만 강제 요구를 연다.</li><li>동시 제안은 같은 주간 스냅샷으로 평가한 뒤 명령 ID 순서로 정산한다.</li><li>공성 접근로와 보급과 퇴로를 4방향 시야와 공간으로 고정한다.</li><li>시작 시 확정된 전투 컨텍스트만 쓴다. 보급일 0이면 전투 계수 0.60을 넣고 다음 무보급 공성일을 막는다.</li><li>접근 용량 안에서만 완전 전력을 투입한다. 나머지는 예비·지원이다.</li><li>압박증가와 피로계수와 적재계수를 적용한다. <code>P&gt;=40</code>과 <code>B</code> 누적에서 돌파를 연다.</li><li>합법 퇴로가 있으면 질서철수를 허용한다. <code>LegalFallback</code> 실패면 패주손실을 넣는다.</li><li>종료 결과는 <code>ResultId</code>로 한 번만 캠페인에 반영한다. 점령 승리에 시설 복구와 주민 협력을 자동으로 붙이지 않는다.</li><li>주둔요구를 계산하고 점령 직후 치안 20에서 안정화를 연다.</li></ol><h2 id="금지-사항" tabindex="-1">금지 사항 <a class="header-anchor" href="#금지-사항" aria-label="Permalink to &quot;금지 사항&quot;">​</a></h2><ul><li>호감도 하나로 외교를 접지 말 것</li><li>불가능한 약속을 교섭 능력으로 통과시키지 말 것</li><li>정치 자본 지출로 신뢰나 정통성을 직접 바꾸지 말 것</li><li>압력 70과 지렛대 0.75가 2주 연속이 아닌데 강제 요구를 열지 말 것</li><li>고립으로 현지 정통성을 자동으로 깎지 말 것</li><li>후계 교체 때 개인 약속과 제도 약속을 한 덩어리로 덮지 말 것</li><li>동시 제안의 난수를 다시 굴려 순서를 바꾸지 말 것</li><li>병력 수 비교만으로 전쟁을 닫지 말 것</li><li>보급일 0에서 다음 무보급 공성일을 지속하지 말 것</li><li><code>LegalFallback</code> 실패를 질서철수로 처리하지 말 것</li><li>점령 승리에 시설 복구와 주민 협력을 자동 부여하지 말 것</li><li>접근 용량을 넘는 동시 공격에 완전 전력을 주지 말 것</li><li>전투 결과를 <code>ResultId</code> 없이 두 번 반영하지 말 것</li><li>설계 가정 수치를 구현 상수보다 앞세우지 말 것</li><li>고립 단계 0~2와 과확장 0~2를 다른 범위로 바꾸지 말 것</li></ul><h2 id="출처" tabindex="-1">출처 <a class="header-anchor" href="#출처" aria-label="Permalink to &quot;출처&quot;">​</a></h2><ul><li><code>docs/game-logic/Factions-and-Diplomacy.md</code> — 입력 축과 Rel·신뢰·압력 공식과 회의 비용과 강제 요구 문턱. 본문 표기는 설계 가정.</li><li><code>docs/game-logic/Warfare-and-Sieges.md</code> — 작전 입력과 전투 계수와 압박·패주·주둔 공식과 보급·퇴로 경계. 본문 표기는 설계 가정.</li><li>수치 충돌: 외교 결속 <code>C</code> 기본값 0과 작전 결속 <code>C</code> 기본값 70은 도메인이 다르다. 같은 계약 값이 아니다.</li><li>계약·잠긴 표기는 두 원문에 없었다. 구현 상수가 생기면 그 값을 우선한다.</li><li>검산 고정: Rel 0.53. 압력 73. 압박증가 6. 피로계수 0.8. 패주손실 32.</li></ul>',79)])])}const f=a(l,[["render",o]]);export{A as __pageData,f as default};
